#[test]
fn truth_table_root_alternative_string_classes_preserve_deep_branches_and_conditional_empty_identity()
 {
    let pattern = JsString::from(
        format!(
            r"{}((^)|(\b)){}(?<c>[\q{{}}])|((\b\B)|(\b\B))",
            "(".repeat(1000),
            ")".repeat(1000)
        )
        .as_str(),
    );
    check(&format!(
        "var m=new RegExp({pattern:?},'dv').exec('');m[0]===''&&m.length===1008&&m[1]===''&&m[1002]===''&&m[1003]===undefined&&m.groups.c===''&&m[1005]===undefined&&m.indices.groups.c===m.indices[1004]&&m.indices[1004][0]===0&&m.indices[1004][1]===0"
    ));
    check(
        r"var r=/((^)|(\b))(?<c>[\q{ab!|a}])((^)|(\B))|((\b\B)|(\b\B))/dv,m=r.exec('ab!Z');m[0]==='a'&&m.groups.c==='a'&&m[6]===undefined&&m[7]===''&&m[8]===undefined&&m.indices.groups.c[0]===0&&m.indices.groups.c[1]===1",
    );
    check(
        r"var r=/((\b\B)|(\b\B))()|(($)|(\b))(?<c>[\q{}])/dvg,m=r.exec('!a');m[0]===''&&m.index===1&&m.groups.c===''&&m[1]===undefined&&m[4]===undefined&&m[7]===''&&m.indices.groups.c===m.indices[8]&&m.indices[8][0]===1&&m.indices[8][1]===1&&r.lastIndex===1",
    );
    check(
        r"var r=/((\b)|(\B))(?<e>)|((^)|(\b))(?<c>[\q{|a|ab}])/dv,m=r.exec('ab');m[0]===''&&m.groups.e===''&&m.groups.c===undefined&&m[2]===''&&m[3]===undefined&&m[5]===undefined&&m.indices.groups.e===m.indices[4]",
    );
    check(
        r"var r=/((^)|(\b))($(?<c>[\q{\n|\na}])^)(($)|(\b))|((\b\B)|(\b\B))/dvm,m=r.exec('\na');m[0]==='\n'&&m.groups.c==='\n'&&m.indices.groups.c[0]===0&&m.indices.groups.c[1]===1",
    );
    let word = "x".repeat(20_000);
    let pattern = JsString::from(
        format!(r"((^)|(\b))(?<c>[\p{{Any}}\q{{{word}|{word}x}}])(($)|(\B))|((\b\B)|(\b\B))()")
            .as_str(),
    );
    let input = JsString::from(word.as_str());
    check(&format!(
        "var r=new RegExp({pattern:?},'dv'),m=r.exec({input:?}),n=r.exec('x');m[0].length===20000&&m.groups.c.length===20000&&m.indices.groups.c[0]===0&&m.indices.groups.c[1]===20000&&n[0]==='x'&&n.groups.c==='x'"
    ));
    let mut realm = Realm::new(Limits {
        max_steps: Some(30_000),
        ..Limits::default()
    });
    realm.eval("var r=7,marker=0").unwrap();
    assert!(matches!(
        realm.eval(&format!(
            "try{{r=new RegExp({pattern:?},'v')}}catch{{marker=1}}finally{{marker=2}}"
        )),
        Err(Error::Limit { .. })
    ));
    assert_eq!(realm.eval("r===7&&marker===0"), Ok(Value::Boolean(true)));
}
